'use strict';
const fs=require('fs');const path=require('path');const url=require('url');
function express(){
  const routes=[]; const middleware=[];
  const app=function(req,res){
    res.status=function(code){res.statusCode=code;return res};
    res.json=function(obj){if(!res.headersSent)res.setHeader('Content-Type','application/json; charset=utf-8');res.end(JSON.stringify(obj));return res};
    let i=0;
    const run=()=>{ if(i<middleware.length){ const fn=middleware[i++]; return fn(req,res,run); } handle(); };
    const handle=()=>{
      const pathname=url.parse(req.url).pathname;
      const method=req.method;
      const hit=routes.find(r=>r.method===method && (r.path===pathname || r.regex?.test(pathname)));
      if(!hit)return res.status(404).json({error:'Not found'});
      req.params={}; if(hit.regex){const m=pathname.match(hit.regex);hit.keys.forEach((k,n)=>req.params[k]=decodeURIComponent(m[n+1]||''));}
      if(hit.query){req.query=Object.fromEntries(new URL(req.url,'http://local').searchParams.entries());}
      return hit.fn(req,res);
    }; run();
  };
  app.disable=()=>app; app.use=(fn)=>{middleware.push(fn);return app;};
  for(const method of ['get','post','put','patch','delete']) app[method]=(route,fn)=>{let regex=null,keys=[]; if(route.includes(':')){const parts=route.split('/').map(x=>x.startsWith(':')?'__PARAM__':x);const keyParts=route.split('/').filter(Boolean);keys=keyParts.filter(x=>x.startsWith(':')).map(x=>x.slice(1));regex=new RegExp('^'+parts.map((x,i)=>x==='__PARAM__'?'([^/]+)':escapeRegex(x)).join('/')+'/?$');} routes.push({method:method.toUpperCase(),path:regex?null:route,regex,keys,query:true,fn});return app;};
  app.listen=(port,host,cb)=>require('http').createServer(app).listen(port,host,cb);
  return app;
}
function escapeRegex(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');}
express.json=({limit='100kb'}={})=>(req,res,next)=>{if(!['POST','PUT','PATCH','DELETE'].includes(req.method))return next();let data='';let n=0;req.on('data',c=>{n+=c.length;if(n>parseLimit(limit)){res.status(413).json({error:'Payload too large'});req.destroy();return;}data+=c});req.on('end',()=>{if(!data){req.body={};return next();}try{req.body=JSON.parse(data)}catch{req.body=null;return res.status(400).json({error:'JSON inválido.'})}next()});req.on('error',()=>{});};
function parseLimit(v){const m=String(v).match(/^(\d+)\s*(kb|mb|b)?$/i);if(!m)return 262144;const n=Number(m[1]),u=(m[2]||'b').toLowerCase();return n*(u==='mb'?1048576:u==='kb'?1024:1)}
express.static=(root,opts={})=>(req,res,next)=>{if(req.method!=='GET'&&req.method!=='HEAD')return next();let pathname=decodeURIComponent(new URL(req.url,'http://local').pathname);if(pathname.includes('..'))return next();let file=path.join(root,pathname);try{let st=fs.statSync(file);if(st.isDirectory())file=path.join(file,'index.html');st=fs.statSync(file);if(opts.setHeaders)opts.setHeaders(res,file);const types={'.html':'text/html; charset=utf-8','.js':'text/javascript; charset=utf-8','.css':'text/css; charset=utf-8','.json':'application/json; charset=utf-8','.svg':'image/svg+xml','.png':'image/png','.webmanifest':'application/manifest+json'};res.setHeader('Content-Type',types[path.extname(file).toLowerCase()]||'application/octet-stream');res.setHeader('Content-Length',st.size);const stream=fs.createReadStream(file);stream.on('error',()=>next());if(req.method==='HEAD'){res.end();stream.destroy()}else stream.pipe(res)}catch{next()}};
const old=express;module.exports=old;
